import{_ as o,o as a,c as d,a2 as i}from"./chunks/framework.w09axK8o.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":null}'),l={name:"guide/faq.md"};function c(n,e,r,t,s,h){return a(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="安装失败-提示-插件包内未找到-plugin-json" tabindex="-1">安装失败，提示“插件包内未找到 plugin.json” <a class="header-anchor" href="#安装失败-提示-插件包内未找到-plugin-json" aria-label="Permalink to &quot;安装失败，提示“插件包内未找到 plugin.json”&quot;">​</a></h2><ul><li>确认 zip 内确实有一份 <code>plugin.json</code>。</li><li><code>plugin.json</code> 必须在有效根：根目录，或仅含一个顶层插件的子目录。</li><li>文件必须是 UTF-8 编码的合法 JSON，且 <code>id</code>/<code>name</code>/<code>version</code> 均非空。</li></ul><h2 id="提示-插件-id-不匹配" tabindex="-1">提示“插件 id 不匹配” <a class="header-anchor" href="#提示-插件-id-不匹配" aria-label="Permalink to &quot;提示“插件 id 不匹配”&quot;">​</a></h2><p><code>index.json</code> 里的 <code>id</code> 与 zip 内 <code>plugin.json</code> 的 <code>id</code> 不一致。两者必须相等。</p><h2 id="市场里看不到我的插件" tabindex="-1">市场里看不到我的插件 <a class="header-anchor" href="#市场里看不到我的插件" aria-label="Permalink to &quot;市场里看不到我的插件&quot;">​</a></h2><ul><li>确认已更新仓库根的 <code>index.json</code> 并提交到 <code>master</code>。</li><li>确认 <code>downloadUrl</code> 的 raw 直链可访问（返回 200）。</li><li>确认 <code>index.json</code> 的 <code>plugins</code> 结构正确（是数组，字段名拼写无误）。</li></ul><h2 id="市场卡片没有图标" tabindex="-1">市场卡片没有图标 <a class="header-anchor" href="#市场卡片没有图标" aria-label="Permalink to &quot;市场卡片没有图标&quot;">​</a></h2><p>留空 <code>icon</code> 时前端会用分类默认图标；如需自定义，给 <code>icon</code> 填一个可访问的图片 URL。</p><h2 id="想更新插件版本" tabindex="-1">想更新插件版本 <a class="header-anchor" href="#想更新插件版本" aria-label="Permalink to &quot;想更新插件版本&quot;">​</a></h2><ol><li>修改包内 <code>plugin.json</code> 的 <code>version</code>，重新打 zip 并上传。</li><li>更新 <code>index.json</code> 中的 <code>version</code>、<code>sha256</code>、<code>size</code>（与新的 zip 一致）。</li><li>提交后，已安装用户会在市场看到“更新”按钮。</li></ol><h2 id="插件安装后想去掉" tabindex="-1">插件安装后想去掉 <a class="header-anchor" href="#插件安装后想去掉" aria-label="Permalink to &quot;插件安装后想去掉&quot;">​</a></h2><p>在插件市场中该插件的“已安装”状态点“卸载”，或删除 <code>data/plugins/&lt;id&gt;/</code> 目录。</p><h2 id="去哪里提问" tabindex="-1">去哪里提问 <a class="header-anchor" href="#去哪里提问" aria-label="Permalink to &quot;去哪里提问&quot;">​</a></h2><p>插件仓库：<a href="https://gitee.com/doujie081231/verseplugin" target="_blank" rel="noreferrer">https://gitee.com/doujie081231/verseplugin</a></p>',15)])])}const f=o(l,[["render",c]]);export{p as __pageData,f as default};
